// We use the Verus prelude for specifications and proofs.
use verus::prelude::*;

verus! {

    /// Returns `true` iff every element of the slice `a` equals `n`.
    /// 
    /// Specification:
    ///   - If the function returns `true`, then for every valid index `j`
    ///     (0 ≤ j < a.len()), we have a[j] == n.
    ///   - If the function returns `false`, then there exists a valid index `j`
    ///     (0 ≤ j < a.len()) such that a[j] != n.
    pub fn all_elements_equal(a: &[i32], n: i32) -> bool
        ensures |res: bool| 
            (res ==> forall |j: nat| j < a.len() ==> a[j] == n)
            &&
            (!res ==> exists |j: nat| j < a.len() && a[j] != n)
    {
        // We'll scan the array from index 0 up to a.len().
        let mut i: nat = 0;

        // Invariant: 0 ≤ i ≤ a.len(), and 
        //            for all j < i, a[j] == n.
        // Decreases: a.len() - i  (to prove termination).
        while i < a.len()
            invariant  i <= a.len()
            invariant  forall |j: nat| j < i ==> a[j] == n
            decreases a.len() - i
        {
            if a[i] != n {
                // We found a counterexample, so we can return false.
                return false;
            }
            i = i + 1;
        }

        // If we reach here, every element a[0..a.len()) was equal to n.
        true
    }
}